            files = [f"{path}/{self.split}-{idx:05d}-of-{len(files):05d}.parquet" for idx in range(1, len(files) + 1)]
        else:
            files = self.fs.glob(f"{path}/*.parquet")

        logger.info(f"files in path: {files}")
        for file in files:
